/** Loads issues in the given id order, with label ids in insertion order. */
export async function findIssuesInOrder(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.id, [...issueIds]),
      ),
    )
    .all();
  const byId = new Map(rows.map((row) => [row.id, row]));

  const labelRows = getDb()
    .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .orderBy(sql`rowid`)
    .all();

  const labelsByIssue: Record<string, LabelId[]> = {};
  for (const row of labelRows) {
    (labelsByIssue[row.issueId] ??= []).push(row.labelId as LabelId);
  }

  const found: Issue[] = [];
  for (const issueId of issueIds) {
    const row = byId.get(issueId);
    if (row) found.push(toIssue(row, labelsByIssue[issueId] ?? []));
  }
  return found;
}

