/**
 * Turns every row of an upload into an issue, in file order, or returns the
 * issues a previous upload with the same workspace key already created.
 * Checks (scope, project, permission, quota, rate limit, unknown labels)
 * finish before the first write. A refusal persists nothing, including the key.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await issueImportRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (existing) {
    const issues = await issueRepo.findIssuesInOrder(
      input.orgId,
      existing.issueIds,
    );
    return {
      importKey: existing.importKey,
      projectId: existing.projectId,
      issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const members = await memberRepo.listActiveMemberEmails(input.orgId);
  const assigneeByEmail = new Map<string, UserId>(
    members.map((member) => [member.email.toLowerCase(), member.userId]),
  );

  const knownLabels = await labelRepo.listLabels(input.orgId);
  const labelIdByName = new Map<string, LabelId>(
    knownLabels.map((label) => [label.name, label.id]),
  );

  const issues = await runInTransaction(async () => {
    const namesToCreate: string[] = [];
    const seenNew = new Set<string>();
    for (const row of input.rows) {
      for (const name of row.labels) {
        if (labelIdByName.has(name) || seenNew.has(name)) continue;
        seenNew.add(name);
        namesToCreate.push(name);
      }
    }

    for (const name of namesToCreate) {
      const created = await labelRepo.insertLabel({
        orgId: input.orgId,
        name,
        color: DEFAULT_LABEL_COLOR,
        description: null,
      });
      labelIdByName.set(created.name, created.id);
    }

    const startNumber = await issueRepo.nextIssueNumber(
      input.orgId,
      input.projectId,
    );

    const createdIssues: Issue[] = [];
    for (let index = 0; index < input.rows.length; index += 1) {
      const row = input.rows[index]!;
      const labelIds: LabelId[] = [];
      const seenInRow = new Set<string>();
      for (const name of row.labels) {
        if (seenInRow.has(name)) continue;
        seenInRow.add(name);
        const labelId = labelIdByName.get(name);
        if (labelId) labelIds.push(labelId);
      }

      const email = row.assigneeEmail?.toLowerCase() ?? null;
      const assigneeId =
        email === null ? null : (assigneeByEmail.get(email) ?? null);

      const issue = await issueRepo.insertIssue(
        {
          orgId: input.orgId,
          projectId: input.projectId,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          labelIds,
        },
        actor.userId,
        startNumber + index,
      );
      createdIssues.push(issue);
    }

    await issueImportRepo.insertIssueImport(
      input.orgId,
      input.importKey,
      input.projectId,
      createdIssues.map((issue) => issue.id),
    );

    return createdIssues;
  });

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

